<template>
  <view-port>
    <div class="view-port-content">
      <div v-if="testAttributeGroups.length === 0" class="no-attributes">
        <ion-text color="medium">
          <p>No test attributes required for selected tests.</p>
        </ion-text>
      </div>

      <div v-for="group in testAttributeGroups" :key="group.testName" class="attribute-group">
        <div class="group-header">
          <h3>{{ group.testName }}</h3>
        </div>

        <ion-list class="his-card">
          <div v-for="attr in group.attributes" :key="`${attr.fieldId}_${renderKey}`" class="attribute-field">
            <!-- Check if attribute should be shown based on parent condition -->
            <template v-if="shouldShowAttribute(attr)">
              <!-- Radio Buttons - needs special layout -->
              <div v-if="attr.field_type === 'radio' && attr.options" class="radio-field">
                <ion-list-header>
                  <ion-label>{{ attr.attribute_label }}{{ attr.is_required ? ' *' : '' }}</ion-label>
                </ion-list-header>
                <ion-radio-group v-model="attributeValues[attr.fieldId]" @ionChange="handleValueChange">
                  <ion-item v-for="option in attr.options" :key="option" lines="none">
                    <ion-radio slot="start" :value="option"></ion-radio>
                    <ion-label>{{ option }}</ion-label>
                  </ion-item>
                </ion-radio-group>
              </div>

              <!-- All other field types -->
              <ion-item v-else>
                <ion-label position="floating">
                  {{ attr.attribute_label }}{{ attr.is_required ? ' *' : '' }}
                </ion-label>

                <!-- Text Input -->
                <ion-input v-if="attr.field_type === 'text'" v-model="attributeValues[attr.fieldId]"
                  :placeholder="attr.attribute_label" @ionChange="handleValueChange"></ion-input>

                <!-- Number Input -->
                <ion-input v-else-if="attr.field_type === 'number'" v-model.number="attributeValues[attr.fieldId]"
                  type="number" :placeholder="attr.attribute_label" @ionChange="handleValueChange"></ion-input>

                <!-- Date Input -->
                <ion-datetime v-else-if="attr.field_type === 'date'" v-model="attributeValues[attr.fieldId]"
                  presentation="date" @ionChange="handleValueChange"></ion-datetime>

                <!-- Yes/No Select -->
                <ion-select v-else-if="attr.field_type === 'yes_no'" v-model="attributeValues[attr.fieldId]"
                  :placeholder="'Select ' + attr.attribute_label" @ionChange="handleValueChange">
                  <ion-select-option value="Yes">Yes</ion-select-option>
                  <ion-select-option value="No">No</ion-select-option>
                </ion-select>

                <!-- Select/Dropdown -->
                <ion-select v-else-if="attr.field_type === 'select' && attr.options"
                  v-model="attributeValues[attr.fieldId]" :placeholder="'Select ' + attr.attribute_label"
                  @ionChange="handleValueChange">
                  <ion-select-option v-for="option in attr.options" :key="option" :value="option">
                    {{ option }}
                  </ion-select-option>
                </ion-select>

                <!-- Textarea -->
                <ion-textarea v-else-if="attr.field_type === 'textarea'" v-model="attributeValues[attr.fieldId]"
                  :placeholder="attr.attribute_label" :rows="3" @ionChange="handleValueChange"></ion-textarea>

                <!-- Checkbox (for boolean attributes) -->
                <ion-checkbox v-else-if="attr.field_type === 'checkbox'" v-model="attributeValues[attr.fieldId]"
                  @ionChange="handleValueChange"></ion-checkbox>
              </ion-item>
            </template>
          </div>
        </ion-list>
      </div>
    </div>
  </view-port>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Option } from '../Forms/FieldInterface';
import ViewPort from '@/components/DataViews/ViewPort.vue';
import FieldMixinVue from './FieldMixin.vue';
import {
  IonInput,
  IonTextarea,
  IonSelect,
  IonSelectOption,
  IonDatetime,
  IonRadioGroup,
  IonRadio,
  IonCheckbox,
  IonItem,
  IonLabel,
  IonList,
  IonListHeader,
  IonText,
} from '@ionic/vue';

export default defineComponent({
  components: {
    ViewPort,
    IonInput,
    IonTextarea,
    IonSelect,
    IonSelectOption,
    IonDatetime,
    IonRadioGroup,
    IonRadio,
    IonCheckbox,
    IonItem,
    IonLabel,
    IonList,
    IonListHeader,
    IonText,
  },
  mixins: [FieldMixinVue],
  data() {
    return {
      attributeValues: {} as Record<string, any>,
      testAttributeGroups: [] as Array<{
        testName: string;
        attributes: Array<any>;
      }>,
      renderKey: 0,
    };
  },
  mounted() {
    this.init();
  },
  activated() {
    this.init();
  },
  methods: {
    async init() {
      this.$emit('onFieldActivated', this);
      this.buildAttributeGroups();
    },
    buildAttributeGroups() {
      // Get the rawTestTypes and getDisplayName from field config
      const rawTestTypes = (this as any).config?.rawTestTypes || [];
      const getDisplayName = (this as any).config?.getDisplayName || ((name: string) => name);
      const selectedTestTypes = this.fdata?.test_types || [];

      this.testAttributeGroups = [];
      const groups: Array<any> = [];

      if (selectedTestTypes && selectedTestTypes.length > 0 && rawTestTypes && rawTestTypes.length > 0) {
        selectedTestTypes.forEach((selectedTest: any) => {
          const testDisplayName = typeof selectedTest === 'string' ? selectedTest : selectedTest.label;

          // Find the corresponding raw test type
          const rawTestType = rawTestTypes.find((rt: any) => {
            const rtDisplayName = getDisplayName(rt.name, rt.preferred_name);
            return rtDisplayName === testDisplayName;
          });

          if (rawTestType && rawTestType.attributes && rawTestType.attributes.length > 0) {
            // Process all attributes including nested child attributes
            const processAttributes = (attrs: any[], testName: string): any[] => {
              const processed: any[] = [];

              attrs.forEach((attr: any) => {
                // Add the main attribute
                processed.push({
                  fieldId: `${testName}_${attr.attribute_id}`,
                  attribute_id: attr.attribute_id,
                  is_required: attr.is_required,
                  parent_attribute_id: attr.parent_attribute_id,
                  parent_attribute_value: attr.parent_attribute_value,
                  attribute_label: attr.attribute?.label || attr.attribute?.name || 'Attribute',
                  field_type: attr.attribute?.field_type || 'text',
                  options: attr.effective_options || attr.attribute?.options || [],
                });

                // Recursively process child attributes
                if (attr.child_attributes && attr.child_attributes.length > 0) {
                  processed.push(...processAttributes(attr.child_attributes, testName));
                }
              });

              return processed;
            };

            const attributesWithFieldIds = processAttributes(rawTestType.attributes, testDisplayName);

            groups.push({
              testName: testDisplayName,
              attributes: attributesWithFieldIds,
            });
          }
        });
      }

      this.testAttributeGroups = groups;

      // Initialize attributeValues if test_attributes exist in fdata
      if (this.fdata?.test_attributes) {
        this.attributeValues = { ...this.fdata.test_attributes };
      }
    },
    shouldShowAttribute(attr: any): boolean {
      // Always show attributes without parent (top-level attributes)
      if (!attr.parent_attribute_id || !attr.parent_attribute_value) {
        return true;
      }

      // Find the parent attribute's field ID pattern
      // We need to find which test this attribute belongs to
      for (const group of this.testAttributeGroups) {
        // Check if this attribute belongs to this group
        if (attr.fieldId.startsWith(group.testName)) {
          // Find the parent attribute in the same group
          const parentAttr = group.attributes.find(
            (a: any) => a.attribute_id === attr.parent_attribute_id
          );

          if (parentAttr) {
            // Check if parent's value matches the required value
            const parentValue = this.attributeValues[parentAttr.fieldId];
            return parentValue === attr.parent_attribute_value;
          }
        }
      }

      return false;
    },
    handleValueChange() {
      // Increment render key to force re-render and show/hide conditional attributes
      this.renderKey++;
      // Emit the value whenever any attribute changes
      this.emitValue();
    },
    async emitValue() {
      const value: Option = {
        label: 'Test Attributes',
        value: JSON.stringify(this.attributeValues),
        other: { test_attributes: this.attributeValues },
      };

      if (this.onValue) {
        const ok = await this.onValue(value);
        if (!ok) {
          return;
        }
      }

      this.$emit('onValue', value);
    },
  },
  watch: {
    'fdata.test_types': {
      handler() {
        // Rebuild groups when test types change
        this.buildAttributeGroups();
      },
      deep: true,
    },
  },
});
</script>

